solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <optional>
#include <vector>

struct Path { std::uint64_t base; std::vector<std::int64_t> offsets; };

class AddressSpace
{
public:
    void map(std::uint64_t start, std::vector<std::uint8_t> bytes, bool isStatic)
    {
        regions.push_back({ start, std::move(bytes), isStatic });
    }

    std::optional<std::uint64_t> read64(std::uint64_t address) const { return read(address, 8); }

    std::optional<std::uint32_t> read32(std::uint64_t address) const
    {
        const auto v{ read(address, 4) };
        if (!v) return std::nullopt;
        return static_cast<std::uint32_t>(*v);
    }

    std::vector<std::uint64_t> staticPointerSlots() const
    {
        std::vector<std::uint64_t> slots;
        for (const Region& r : regions)
        {
            if (!r.isStatic) continue;
            for (std::uint64_t a{ (r.start + 7) / 8 * 8 }; a + 8 <= r.start + r.bytes.size(); a += 8) slots.push_back(a);
        }
        std::sort(slots.begin(), slots.end());
        return slots;
    }

private:
    struct Region { std::uint64_t start; std::vector<std::uint8_t> bytes; bool isStatic; };
    std::vector<Region> regions;

    std::optional<std::uint64_t> read(std::uint64_t address, int size) const
    {
        for (const Region& r : regions)
        {
            if (address < r.start || address - r.start + size > r.bytes.size()) continue;
            std::uint64_t value{ 0 };
            const std::uint64_t at{ address - r.start };
            for (int i{ 0 }; i < size; ++i) value |= static_cast<std::uint64_t>(r.bytes[at + i]) << (8 * i);
            return value;
        }
        return std::nullopt;
    }
};

std::optional<std::uint64_t> resolve(const AddressSpace& memory, const Path& path)
{
    auto current{ memory.read64(path.base) };
    if (!current || *current == 0) return std::nullopt;
    if (path.offsets.empty()) return current;
    for (std::size_t i{ 0 }; i + 1 < path.offsets.size(); ++i)
    {
        current = memory.read64(*current + static_cast<std::uint64_t>(path.offsets[i]));
        if (!current || *current == 0) return std::nullopt;
    }
    return *current + static_cast<std::uint64_t>(path.offsets.back());
}

std::vector<Path> scan(const AddressSpace& memory, std::uint64_t target, std::int64_t maxOffset, int maxDepth)
{
    std::vector<Path> found;
    const auto near = [&](std::uint64_t p) { return p != 0 && p <= target && static_cast<std::int64_t>(target - p) <= maxOffset; };
    for (std::uint64_t slot : memory.staticPointerSlots())
    {
        const auto p1{ memory.read64(slot) };
        if (!p1 || *p1 == 0) continue;
        if (maxDepth >= 1 && near(*p1)) found.push_back({ slot, { static_cast<std::int64_t>(target - *p1) } });
        if (maxDepth < 2) continue;
        for (std::int64_t o1{ 0 }; o1 <= maxOffset; o1 += 8)
        {
            const auto p2{ memory.read64(*p1 + static_cast<std::uint64_t>(o1)) };
            if (p2 && near(*p2)) found.push_back({ slot, { o1, static_cast<std::int64_t>(target - *p2) } });
        }
    }
    std::sort(found.begin(), found.end(), [](const Path& a, const Path& b) {
        if (a.base != b.base) return a.base < b.base;
        if (a.offsets.size() != b.offsets.size()) return a.offsets.size() < b.offsets.size();
        return a.offsets < b.offsets;
    });
    return found;
}

hints:
`std::optional<T>` (from `<optional>`) holds either a `T` or nothing. Return a plain value to give a result and `std::nullopt` for "no result"; the caller tests it like a pointer and reads it with `*`:
```cpp
std::optional<std::uint64_t> p{ memory.read64(address) };
if (!p || *p == 0) return std::nullopt;   // failed read or null pointer
std::uint64_t next{ *p + offset };
```

unitTests:
#include <cstring>
static std::vector<std::uint8_t> zeros(std::size_t n) { return std::vector<std::uint8_t>(n, 0); }
static void put64(std::vector<std::uint8_t>& b, std::size_t at, std::uint64_t v) { for (int i{ 0 }; i < 8; ++i) b[at + i] = static_cast<std::uint8_t>(v >> (8 * i)); }
static void put32(std::vector<std::uint8_t>& b, std::size_t at, std::uint32_t v) { for (int i{ 0 }; i < 4; ++i) b[at + i] = static_cast<std::uint8_t>(v >> (8 * i)); }

// A tiny "game": a global Game* in the static image, a Game on the heap pointing at a Player, whose health is 87.
static AddressSpace sample()
{
    auto image{ zeros(0x40) }; put64(image, 0x10, 0x20000);           // global Game* at 0x1010
    auto game{ zeros(0x30) };  put64(game, 0x08, 0x30000);            // Game: player pointer at +8
    auto player{ zeros(0x40) }; put32(player, 0x24, 87);              // Player: health at +0x24
    AddressSpace m;
    m.map(0x1000, image, true);
    m.map(0x20000, game, false);
    m.map(0x30000, player, false);
    return m;
}

TEST("reads stay inside regions") {
    AddressSpace m{ sample() };
    CHECK_EQ(m.read64(0x1010).value_or(1), 0x20000ull);
    CHECK_EQ(m.read32(0x30024).value_or(0), 87u);
    CHECK(!m.read64(0x1039).has_value());
    CHECK(m.read64(0x1038).has_value());
    CHECK(!m.read32(0x5000).has_value());
    CHECK(!m.read64(0x0FFC).has_value());
}
TEST("static slots") {
    AddressSpace m;
    m.map(0x2004, zeros(0x1B), true);
    m.map(0x9000, zeros(0x20), false);
    CHECK_EQ(m.staticPointerSlots(), (std::vector<std::uint64_t>{ 0x2008, 0x2010 }));
}
TEST("resolving paths") {
    AddressSpace m{ sample() };
    CHECK_EQ(resolve(m, { 0x1010, { 0x08, 0x24 } }).value_or(0), 0x30024ull);
    CHECK_EQ(m.read32(*resolve(m, { 0x1010, { 0x08, 0x24 } })).value_or(0), 87u);
    CHECK_EQ(resolve(m, { 0x1010, {} }).value_or(0), 0x20000ull);
    CHECK_EQ(resolve(m, { 0x1010, { 0x10 } }).value_or(0), 0x20010ull);
    CHECK(!resolve(m, { 0x1018, { 0x08, 0x24 } }).has_value());
    CHECK(!resolve(m, { 0x1010, { 0x10, 0x24 } }).has_value());
    CHECK(!resolve(m, { 0x1010, { 0x100, 0x24 } }).has_value());
}
TEST("scanning finds the path to health") {
    AddressSpace m{ sample() };
    const auto paths{ scan(m, 0x30024, 0x40, 2) };
    CHECK_EQ(paths.size(), 1u);
    if (!paths.empty()) { CHECK_EQ(paths[0].base, 0x1010ull); CHECK_EQ(paths[0].offsets, (std::vector<std::int64_t>{ 0x08, 0x24 })); }
    CHECK(scan(m, 0x30024, 0x40, 1).empty());
    CHECK(scan(m, 0x30024, 0x20, 2).empty());
}
TEST("several paths, in order") {
    auto image{ zeros(0x20) };
    put64(image, 0x00, 0x30000);     // a second global pointing straight at the player
    put64(image, 0x18, 0x20000);     // and one pointing at the game
    auto game{ zeros(0x20) }; put64(game, 0x00, 0x30000); put64(game, 0x10, 0x30020);
    auto player{ zeros(0x40) };
    AddressSpace m;
    m.map(0x1000, image, true); m.map(0x20000, game, false); m.map(0x30000, player, false);
    const auto paths{ scan(m, 0x30024, 0x40, 2) };
    CHECK_EQ(paths.size(), 3u);
    if (paths.size() == 3)
    {
        CHECK_EQ(paths[0].base, 0x1000ull); CHECK_EQ(paths[0].offsets, (std::vector<std::int64_t>{ 0x24 }));
        CHECK_EQ(paths[1].base, 0x1018ull); CHECK_EQ(paths[1].offsets, (std::vector<std::int64_t>{ 0x00, 0x24 }));
        CHECK_EQ(paths[2].base, 0x1018ull); CHECK_EQ(paths[2].offsets, (std::vector<std::int64_t>{ 0x10, 0x04 }));
    }
    for (const Path& p : paths) CHECK_EQ(resolve(m, p).value_or(0), 0x30024ull);
}

